// Aggregates data/sales.csv by region.
const fs = require('fs');
const rows = fs.readFileSync('data/sales.csv', 'utf8').trim().split('\n').slice(1);
const totals = {};
for (const row of rows) { const [, region, amount] = row.split(','); totals[region] = (totals[region] ?? 0) + Number(amount); }
console.log(totals);
